#ifndef IH01A_CONV_ZCD_H
#define IH01A_CONV_ZCD_H
#include <stdint.h>
/* TIM1 CH2 rising-edge input capture after the TP1941 chain inverts the
 * current-zero polarity. No DMA, no 200kHz interrupt: foreground reads CCR2.
 *
 * Voltage fundamental + -> - time: ARR/4 + D/2 (in timer ticks).
 * D is the same CH3 shift generated by ConvPhase_Calculate().
 * A positive lag means the observed current zero is LATER than the
 * defined voltage zero; sign and one-half-cycle polarity must be validated
 * on the physical current-sense path.
 */
typedef struct {
    uint16_t capture_raw;
    uint16_t phase_deg;
    int16_t lag_deci_deg;  /* [-1800,+1800], positive means later */
    int32_t lag_quarter_ticks;
    uint32_t sequence;
    uint32_t last_ms;
    uint8_t valid;
    uint8_t overcapture_seen; /* expected when UI polls slower than 200kHz */
} ConvZcdSnapshot;
uint8_t ConvZcd_Calculate(uint16_t arr,uint16_t phase_deg,
                           uint16_t ccr2,ConvZcdSnapshot *out);
void ConvZcd_Init(void);
void ConvZcd_StartCapture(void);
void ConvZcd_Invalidate(void); /* discard CCR2 from old ARR/phase */
void ConvZcd_Poll(uint32_t now_ms);
void ConvZcd_GetSnapshot(ConvZcdSnapshot *out);
#endif
